// Mühazirələr, proqramın 31–42-ci bəndləri. Mənbə: Maliyyə Nazirliyinin rəsmi standart mətnləri; "m." — maddə nömrəsi.
(function () {
  const { P, U, E, J, TB, W, add } = PMS.lec, T = PMS.T;

  add(31, 'ifrs6', 'Maliyyə Hesabatlarının Beynəlxalq Standartları', '6 №-li MHBS — Təbii ehtiyatların kəşfiyyatı və qiymətləndirilməsi', T.N, ['MHBS6', 'UCOT'],
    'Standart faydalı qazıntıların kəşfiyyatı və qiymətləndirilməsi məsrəflərinin uçotunu qismən tənzimləyir. Proqramda bu standartdan məqsəd və tətbiq sahəsi tələb olunur.',
    [
      P('Məqsəd',
        'Standartın məqsədi təbii ehtiyatların kəşfiyyatı və qiymətləndirilməsi ilə bağlı maliyyə hesabatlarının tərtibini müəyyən etməkdir. O, xüsusilə: belə məsrəflər üçün mövcud uçot təcrübəsinə məhdud təkmilləşdirmələr; kəşfiyyat və qiymətləndirmə aktivlərini tanıyan müəssisələrin bu aktivləri 36 №-li MUBS-a əsasən qiymətdən düşməyə yoxlamasını; bu aktivlərin məbləğlərini müəyyən edən və izah edən açıqlamaları tələb edir (m. 1).'),
      P('Tətbiq sahəsi',
        'Müəssisə standartı özünün çəkdiyi kəşfiyyat və qiymətləndirmə məsrəflərinə tətbiq edir (m. 3). Standart təbii ehtiyatların kəşfiyyatı və qiymətləndirilməsindən əvvəl (məsələn, ərazidə kəşfiyyat üçün hüquqi hüquqlar əldə edilməzdən əvvəl) və hasilatın texniki mümkünlüyü və kommersiya sərfəliliyi nümayiş etdirildikdən sonra çəkilən məsrəflərə tətbiq edilmir (m. 5).',
        'Kəşfiyyat və qiymətləndirmə müəssisənin müəyyən ərazidə kəşfiyyat üçün hüquqi hüquqlar əldə etdikdən sonra faydalı qazıntıların (neft, təbii qaz və oxşar bərpa olunmayan ehtiyatlar) axtarışı, habelə onların hasilatının texniki mümkünlüyünün və kommersiya sərfəliliyinin müəyyən edilməsidir (Əlavə A).',
        'Müəssisə hansı məsrəfləri kəşfiyyat və qiymətləndirmə aktivi kimi tanıyacağını müəyyən edən uçot siyasətini seçir və ardıcıl tətbiq edir (m. 9). Belə aktivlər ilkin dəyərlə ölçülür (m. 8); faktlar və şəraitlər onların balans dəyərinin bərpa edilə bilən məbləğdən çox ola biləcəyini göstərdikdə qiymətdən düşməyə yoxlanılır (m. 18).'),
      J('Azərbaycanda tətbiqi — hesablar planı', '<b>141</b> Təbii sərvətlərin (ehtiyatların) dəyəri · <b>142</b> Təbii sərvətlərin (ehtiyatların) tükənməsi'),
    ]);

  add(32, 'ifrs7', 'Maliyyə Hesabatlarının Beynəlxalq Standartları', '7 №-li MHBS — Maliyyə alətləri: Məlumatın açıqlanması', T.N, ['MHBS7'],
    'Standart maliyyə alətlərinin tanınması və ölçülməsini deyil, onlar barədə açıqlamaları tənzimləyir. Proqramda məqsəd və tətbiq sahəsi tələb olunur.',
    [
      P('Məqsəd',
        'Standartın məqsədi müəssisələrdən hesabatlarında elə açıqlamalar verilməsini tələb etməkdir ki, istifadəçilər qiymətləndirə bilsinlər (m. 1): maliyyə alətlərinin müəssisənin maliyyə vəziyyəti və nəticələri üçün əhəmiyyətini; dövr ərzində və hesabat tarixində müəssisənin məruz qaldığı maliyyə alətlərindən yaranan risklərin xarakterini və həcmini və müəssisənin bu riskləri necə idarə etdiyini.',
        'Standart 32 №-li MUBS-un təqdimat prinsiplərini və 9 №-li MHBS-in tanınma və ölçmə prinsiplərini tamamlayır (m. 2).'),
      P('Tətbiq sahəsi və əsas açıqlamalar',
        'Standart bütün müəssisələr tərəfindən bütün növ maliyyə alətlərinə tətbiq edilir; istisnalar 32 №-li MUBS-dakı istisnalara oxşardır — törəmə, asılı və birgə müəssisələrdəki paylar, işçi mükafatları üzrə hüquq və öhdəliklər, sığorta müqavilələri, pay alətləri əsasında ödəmələr (m. 3).',
        'Açıqlamaların iki əsas qrupu var: maliyyə alətlərinin maliyyə vəziyyəti və nəticələr üçün əhəmiyyəti (kateqoriyalar üzrə balans dəyərləri, ədalətli dəyər, gəlir və xərclər); və maliyyə alətlərindən yaranan risklərin xarakteri və həcmi. Risklər üzrə müəssisə ən azı kredit riski, likvidlik riski və bazar riski barədə keyfiyyət və kəmiyyət açıqlamaları verir (m. 31–42).'),
      W('Bu standart nəyin necə ölçüldüyünü deyil, nəyin açıqlandığını müəyyən edir. Riskin üç növünü — kredit, likvidlik, bazar — yadda saxlayın.'),
    ]);

  add(33, 'ifrs8', 'Maliyyə Hesabatlarının Beynəlxalq Standartları', '8 №-li MHBS — Əməliyyat seqmentləri', T.N, ['MHBS8'],
    'Standart müəssisədən istifadəçilərin onun fəaliyyət növlərini və fəaliyyət göstərdiyi iqtisadi mühiti qiymətləndirməsinə imkan verən seqment məlumatlarını açıqlamağı tələb edir. Yanaşma "rəhbərliyin gözü ilə" adlanır.',
    [
      P('Əsas prinsip və tətbiq sahəsi',
        'Müəssisə istifadəçilərə onun məşğul olduğu biznes fəaliyyətinin xarakterini və maliyyə təsirlərini və fəaliyyət göstərdiyi iqtisadi mühiti qiymətləndirməyə imkan verən məlumatları açıqlamalıdır (m. 1).',
        'Standart borc və ya pay alətləri açıq bazarda (yerli və ya xarici fond birjasında və ya birjadankənar bazarda) dövriyyədə olan, yaxud belə alətlərin buraxılması məqsədilə hesabatlarını qiymətli kağızlar komissiyasına və ya digər tənzimləyici orqana təqdim edən və ya təqdim etmə prosesində olan müəssisələrin fərdi və ya konsolidə edilmiş hesabatlarına tətbiq edilir (m. 2).'),
      P('Əməliyyat seqmentləri',
        'Əməliyyat seqmenti müəssisənin elə komponentidir ki (m. 5): gəlir əldə etdiyi və xərc çəkdiyi biznes fəaliyyəti ilə məşğul olur; onun nəticələri resursların bölüşdürülməsi və fəaliyyətin qiymətləndirilməsi barədə qərarlar qəbul etmək üçün müəssisənin əməliyyat qərarlarını qəbul edən baş şəxsi tərəfindən mütəmadi nəzərdən keçirilir; onun üzrə ayrıca maliyyə məlumatı mövcuddur.',
        '"Əməliyyat qərarlarını qəbul edən baş şəxs" vəzifə adı deyil, funksiyadır — bu, baş direktor, baş əməliyyat direktoru və ya direktorlar qrupu ola bilər (m. 7). Korporativ qərargah və bəzi funksional şöbələr gəlir əldə etmirsə, əməliyyat seqmenti deyil (m. 6).'),
      P('Birləşdirmə meyarları və kəmiyyət hədləri',
        'İki və ya daha çox əməliyyat seqmenti oxşar iqtisadi xüsusiyyətlərə malikdirsə və məhsul və xidmətlərin xarakteri, istehsal proseslərinin xarakteri, müştəri növü, paylama metodları və tənzimləyici mühit baxımından oxşardırsa, vahid seqmentdə birləşdirilə bilər (m. 12).',
        'Müəssisə aşağıdakı kəmiyyət hədlərindən hər hansı birinə cavab verən əməliyyat seqmenti haqqında ayrıca məlumat təqdim edir (m. 13): onun xarici və seqmentlərarası gəliri bütün seqmentlərin birgə gəlirinin 10%-i və ya daha çoxudur; onun mənfəəti və ya zərəri mütləq ifadədə mənfəətli seqmentlərin birgə mənfəətinin və ya zərərli seqmentlərin birgə zərərinin (hansı böyükdürsə) 10%-i və ya daha çoxudur; onun aktivləri bütün seqmentlərin birgə aktivlərinin 10%-i və ya daha çoxudur.',
        'Hesabat verilən seqmentlərin xarici gəlirlərinin cəmi müəssisənin gəlirinin 75%-dən azdırsa, bu hədd əldə olunana qədər əlavə seqmentlər hesabat verilən seqment kimi müəyyən edilir (m. 15).'),
      P('Açıqlamalar',
        'Hər hesabat verilən seqment üzrə mənfəət və ya zərər, aktivlər və öhdəliklər (baş şəxsə müntəzəm təqdim edildikdə) və onların ölçülmə əsası açıqlanır (m. 21–23). Müəssisə səviyyəsində məhsul və xidmətlər, coğrafi ərazilər və əsas müştərilər haqqında məlumat verilir; bir xarici müştəri ilə əməliyyatlardan gəlir müəssisənin gəlirinin 10%-i və ya daha çoxu olduqda bu fakt açıqlanır (m. 34).'),
      E('Seqmentlərin gəlirləri: A — 600, B — 250, C — 90, D — 60 min AZN (cəmi 1 000). Yalnız gəlir meyarı nəzərə alınır.',
        '10% həddi = 100 min AZN (m. 13).',
        'A və B hesabat verilən seqmentlərdir; onların payı 85% olduğu üçün 75% tələbi ödənilir (m. 15).'),
    ]);

  add(34, 'ifrs9', 'Maliyyə Hesabatlarının Beynəlxalq Standartları', '9 №-li MHBS — Maliyyə alətləri', T.FI, ['MHBS9', 'MUBS32'],
    'Standart maliyyə aktivləri və maliyyə öhdəliklərinin tanınması, təsnifatı, ölçülməsi, tanınmasının dayandırılması, dəyərsizləşməsi və hecinq uçotu üzrə prinsipləri müəyyən edir. İmtahan baxımından ən vacib hissələr təsnifat, effektiv faiz metodu və gözlənilən kredit zərərləridir.',
    [
      P('Məqsəd və tətbiq sahəsi',
        'Standartın məqsədi maliyyə aktivləri və maliyyə öhdəlikləri barədə hesabatların hazırlanması prinsiplərini müəyyən etməkdir ki, istifadəçilər müəssisənin gələcək pul axınlarının məbləğini, vaxtını və qeyri-müəyyənliyini qiymətləndirə bilsinlər (m. 1.1). Standart 32 №-li MUBS-un əhatə etdiyi bütün maliyyə alətlərinə, istisnalarla (törəmə, asılı və birgə müəssisələrdəki paylar, icarələr üzrə hüquq və öhdəliklərin böyük hissəsi, işçi mükafatları, pay alətləri əsasında ödəmələr və s.) tətbiq edilir (m. 2.1).'),
      P('Tanınma və adi qaydada alış-satış',
        'Müəssisə maliyyə aktivini və ya öhdəliyini yalnız alətin müqavilə şərtlərinin tərəfinə çevrildikdə tanıyır (m. 3.1.1). Maliyyə aktivlərinin adi qaydada alışı və ya satışı (bazarda müəyyən edilmiş müddətdə ötürülməsi nəzərdə tutulan) əməliyyat tarixinə və ya hesablaşma tarixinə uçot metodu ilə tanınır və ya tanınması dayandırılır (m. 3.1.2).'),
      P('Maliyyə aktivlərinin təsnifləşdirilməsi',
        'Müəssisə maliyyə aktivlərini iki əsasda — onların idarə edilməsi üzrə biznes modeli və müqavilə üzrə pul axınlarının xüsusiyyətləri əsasında — sonradan amortizasiya olunmuş dəyərlə, sair məcmu gəlir vasitəsilə ədalətli dəyərlə və ya mənfəət və ya zərər vasitəsilə ədalətli dəyərlə ölçülən kimi təsnif edir (m. 4.1.1).',
        'Amortizasiya olunmuş dəyərlə ölçülür, əgər hər iki şərt ödənilirsə (m. 4.1.2): aktiv məqsədi müqavilə üzrə pul axınlarını əldə etmək üçün aktivləri saxlamaq olan biznes modeli çərçivəsində saxlanılır; və müqavilə şərtləri müəyyən tarixlərdə yalnız əsas məbləğin və ödənilməmiş əsas məbləğə hesablanan faizin ödənilməsindən ibarət pul axınları yaradır (SPPI testi).',
        'Sair məcmu gəlir vasitəsilə ədalətli dəyərlə ölçülür, əgər (m. 4.1.2A): aktiv məqsədi həm müqavilə üzrə pul axınlarını əldə etmək, həm də aktivləri satmaq olan biznes modeli çərçivəsində saxlanılır; və SPPI şərti ödənilir.',
        'Qalan bütün maliyyə aktivləri mənfəət və ya zərər vasitəsilə ədalətli dəyərlə ölçülür (m. 4.1.4). Bununla belə, ticarət üçün saxlanılmayan pay alətinə investisiya üçün müəssisə ilkin tanınmada ədalətli dəyərdəki sonrakı dəyişiklikləri sair məcmu gəlirdə təqdim etməyi geri dönməz şəkildə seçə bilər (m. 4.1.4, 5.7.5).',
        'Maliyyə aktivini mənfəət və ya zərər vasitəsilə ədalətli dəyərlə təyin etmək opsionu: müəssisə ilkin tanınmada aktivi geri dönməz şəkildə belə təyin edə bilər, əgər bu, uçot uyğunsuzluğunu aradan qaldırır və ya əhəmiyyətli dərəcədə azaldırsa (m. 4.1.5).'),
      P('Maliyyə öhdəliklərinin təsnifatı',
        'Bütün maliyyə öhdəlikləri sonradan amortizasiya olunmuş dəyərlə ölçülən kimi təsnif edilir, istisnalar: mənfəət və ya zərər vasitəsilə ədalətli dəyərlə ölçülən öhdəliklər (o cümlədən törəmələr), tanınmanın dayandırılması şərtlərinə cavab verməyən ötürmələrdən yaranan öhdəliklər, maliyyə zəmanəti müqavilələri, bazardan aşağı faizlə kredit vermək öhdəlikləri və şərti ödənişlər (m. 4.2.1).',
        'Maliyyə öhdəliyini mənfəət və ya zərər vasitəsilə ədalətli dəyərlə təyin etmək seçimi uçot uyğunsuzluğunu aradan qaldırdıqda və ya öhdəliklər qrupu ədalətli dəyər əsasında idarə edildikdə tətbiq edilə bilər (m. 4.2.2). Belə öhdəliyin ədalətli dəyərində müəssisənin öz kredit riskinin dəyişməsinə aid hissə sair məcmu gəlirdə, qalan hissə mənfəət və ya zərərdə təqdim edilir (m. 5.7.7).',
        'Maliyyə aktivləri yalnız biznes model dəyişdikdə yenidən təsnif edilir; maliyyə öhdəlikləri yenidən təsnif edilmir (m. 4.4.1–4.4.2).'),
      P('İlkin ölçmə və əməliyyat xərcləri',
        'İlkin tanınmada müəssisə maliyyə aktivini və ya öhdəliyini ədalətli dəyərlə, mənfəət və ya zərər vasitəsilə ədalətli dəyərlə ölçülməyən aktiv və ya öhdəlik olduqda isə üstəgəl (aktiv üçün) və ya çıxılmaqla (öhdəlik üçün) onun alınmasına və ya buraxılmasına birbaşa aid əməliyyat xərcləri ilə ölçür (m. 5.1.1). Əhəmiyyətli maliyyələşdirmə komponenti olmayan ticarət debitor borcları 15 №-li MHBS-də müəyyən edilmiş əməliyyat qiyməti ilə ölçülür (m. 5.1.3).'),
      P('Sonrakı ölçmə və effektiv faiz dərəcəsi metodu',
        'İlkin tanınmadan sonra maliyyə aktivləri təsnifatına uyğun olaraq amortizasiya olunmuş dəyərlə, sair məcmu gəlir vasitəsilə ədalətli dəyərlə və ya mənfəət və ya zərər vasitəsilə ədalətli dəyərlə ölçülür (m. 5.2.1). Maliyyə öhdəlikləri də təsnifatına uyğun ölçülür (m. 5.3.1).',
        'Faiz gəliri effektiv faiz dərəcəsi metodu ilə hesablanır və effektiv faiz dərəcəsi maliyyə aktivinin ümumi balans dəyərinə tətbiq edilir; istisna kredit-dəyərsizləşmiş aktivlərdir — onlar üçün dərəcə amortizasiya olunmuş dəyərə (yəni ehtiyat çıxılmaqla) tətbiq olunur (m. 5.4.1).',
        'Effektiv faiz dərəcəsi maliyyə alətinin gözlənilən müddəti ərzində təxmini gələcək pul ödənişlərini və ya daxilolmalarını onun ümumi balans dəyərinə (və ya öhdəliyin amortizasiya olunmuş dəyərinə) dəqiq diskontlaşdıran dərəcədir (Əlavə A).',
        'Pay alətlərinə investisiyalar: sair məcmu gəlir seçimi tətbiq edildikdə dividendlər mənfəət və ya zərərdə tanınır, ədalətli dəyər dəyişiklikləri isə sair məcmu gəlirdə qalır və sonradan mənfəət və ya zərərə keçirilmir (m. 5.7.5–5.7.6, B5.7.1). Sair məcmu gəlir vasitəsilə ədalətli dəyərlə ölçülən borc aləti üzrə isə faiz gəliri, gözlənilən kredit zərərləri və məzənnə fərqləri mənfəət və ya zərərdə tanınır, aktivin tanınması dayandırıldıqda yığılmış gəlir və ya zərər mənfəət və ya zərərə yenidən təsnif edilir (m. 5.7.10).'),
      E('İstiqraz: nominal 100 000 AZN, illik kupon 5%, 95 000 AZN-ə alınıb, amortizasiya olunmuş dəyərlə ölçülür; effektiv faiz dərəcəsi 6,4%-dir.',
        'Faiz gəliri = 95 000 × 6,4% = 6 080 (mənfəət və ya zərərdə, m. 5.4.1).',
        'Alınan kupon = 100 000 × 5% = 5 000.',
        'Birinci ilin sonunda amortizasiya olunmuş dəyər = 95 000 + 6 080 − 5 000 = <b>96 080 AZN</b>.'),
      P('Dəyərsizləşmə: gözlənilən kredit zərərləri',
        'Müəssisə amortizasiya olunmuş dəyərlə və sair məcmu gəlir vasitəsilə ədalətli dəyərlə ölçülən maliyyə aktivləri, icarə debitorları, müqavilə aktivləri, kredit öhdəlikləri və maliyyə zəmanəti müqavilələri üzrə gözlənilən kredit zərərləri üçün zərər ehtiyatını tanıyır (m. 5.5.1).',
        'Hesabat tarixində maliyyə alətinin kredit riski ilkin tanınmadan bəri əhəmiyyətli dərəcədə artıbsa, müəssisə zərər ehtiyatını bütün müddət üzrə gözlənilən kredit zərərlərinə bərabər məbləğdə ölçür (m. 5.5.3). Əhəmiyyətli dərəcədə artmayıbsa — 12 aylıq gözlənilən kredit zərərlərinə bərabər məbləğdə (m. 5.5.5). Müqavilə üzrə ödənişlər 30 gündən çox gecikdikdə kredit riskinin əhəmiyyətli dərəcədə artdığı barədə təkzib edilə bilən ehtimal mövcuddur (m. 5.5.11).',
        'Sadələşdirilmiş yanaşma: əhəmiyyətli maliyyələşdirmə komponenti olmayan ticarət debitor borcları və müqavilə aktivləri üçün zərər ehtiyatı həmişə bütün müddət üzrə gözlənilən kredit zərərləri ilə ölçülür (m. 5.5.15). Ehtiyatdakı dəyişiklik mənfəət və ya zərərdə dəyərsizləşmə gəliri və ya zərəri kimi tanınır (m. 5.5.8).'),
      TB('Gözlənilən kredit zərərlərinin üç mərhələsi',
        ['Mərhələ', 'Vəziyyət', 'Zərər ehtiyatı', 'Faiz gəliri'],
        ['1', 'Kredit riski əhəmiyyətli artmayıb', '12 aylıq', 'Ümumi balans dəyərinə'],
        ['2', 'Kredit riski əhəmiyyətli artıb', 'Bütün müddət üzrə', 'Ümumi balans dəyərinə'],
        ['3', 'Kredit-dəyərsizləşmiş aktiv', 'Bütün müddət üzrə', 'Amortizasiya olunmuş dəyərə']),
      P('Tanınmanın dayandırılması və hecinq (qısa)',
        'Maliyyə aktivinin tanınması yalnız aktivdən pul axınlarına müqavilə hüquqları başa çatdıqda və ya aktiv ötürüldükdə və ötürmə tanınmanın dayandırılması şərtlərinə (risk və faydaların, nəzarətin ötürülməsi) cavab verdikdə dayandırılır (m. 3.2.3). Müəssisə ötürülmüş aktivin mülkiyyəti ilə bağlı risk və faydaların əsas hissəsini saxlayırsa (məsələn, reqresli faktorinq), aktivin tanınması davam edir və alınan vəsait öhdəlik kimi tanınır (m. 3.2.15). Maliyyə öhdəliyinin tanınması yalnız o, ləğv edildikdə — müqavilədə müəyyən edilmiş öhdəlik icra edildikdə, ləğv olunduqda və ya müddəti bitdikdə dayandırılır (m. 3.3.1).',
        'Hecinq uçotu (6-cı fəsil) üç növ hecinq münasibətini fərqləndirir: ədalətli dəyər hecinqi, pul axınlarının hecinqi və xarici əməliyyata xalis investisiyanın hecinqi (m. 6.5.2). Pul axınlarının hecinqində hecinq alətinin effektiv hissəsi sair məcmu gəlirdə, qeyri-effektiv hissəsi mənfəət və ya zərərdə tanınır (m. 6.5.11).'),
      J('Azərbaycanda tətbiqi — hesablar planı',
        '<b>181/232</b> Ödənişə qədər saxlanılan investisiyalar · <b>231</b> Satış məqsədi ilə saxlanılan qısamüddətli investisiyalar · <b>182/233</b> Verilmiş borclar · <b>184/235</b> Sair maliyyə aktivlərinin dəyərinin azalmasına görə düzəlişlər · <b>218</b> Şübhəli borclar üzrə düzəlişlər',
        'Hesablar planındakı adlar əvvəlki təsnifata əsaslanır; MHBS 9 üzrə ölçmə kateqoriyası aktivin biznes modeli və SPPI testinə əsasən müəyyən edilir.'),
      W('Sair məcmu gəlir vasitəsilə ölçülən borc aləti satıldıqda yığılmış məbləğ mənfəət və ya zərərə keçir, pay aləti üzrə isə keçmir.',
        'Faiz gəliri nominal dəyərə kupon dərəcəsi ilə deyil, balans dəyərinə effektiv faiz dərəcəsi ilə hesablanır.'),
    ], 'ifrs9');

  add(35, 'ifrs10', 'Maliyyə Hesabatlarının Beynəlxalq Standartları', '10 №-li MHBS — Birləşdirilmiş (konsolidə edilmiş) maliyyə hesabatları', T.G, ['MHBS10', 'QANUN', 'TEQDIM'],
    'Standart bir və ya bir neçə başqa müəssisəyə nəzarət edən müəssisənin konsolidə edilmiş hesabatlarının hazırlanması prinsiplərini müəyyən edir. Mərkəzi anlayış nəzarətdir.',
    [
      P('Məqsəd və tətbiq sahəsi',
        'Standartın məqsədi müəssisə bir və ya bir neçə başqa müəssisəyə nəzarət etdikdə konsolidə edilmiş maliyyə hesabatlarının təqdim edilməsi və hazırlanması prinsiplərini müəyyən etməkdir (m. 1). Bu məqsədlə standart: bir və ya bir neçə törəmə müəssisəyə nəzarət edən əsas müəssisədən konsolidə edilmiş hesabatlar təqdim etməyi tələb edir; nəzarət prinsipini konsolidasiyanın əsası kimi müəyyən edir; konsolidə hesabatların hazırlanması üçün uçot tələblərini müəyyən edir; investisiya müəssisəsinin anlayışını verir (m. 2).',
        'Əsas müəssisə konsolidə edilmiş hesabatları təqdim etməyə bilər, əgər bütün şərtlər ödənilirsə (m. 4): o, tam və ya qismən başqa müəssisənin törəmə müəssisəsidir və digər sahibləri bu barədə məlumatlandırılıb və etiraz etmirlər; onun borc və ya pay alətləri açıq bazarda dövriyyədə deyil; o, açıq bazarda alətlərin buraxılması üçün hesabatlarını tənzimləyici orqana təqdim etməyib və təqdim etmə prosesində deyil; onun son və ya aralıq əsas müəssisəsi MHBS-ə uyğun konsolidə edilmiş hesabatları ictimaiyyətə açıq şəkildə hazırlayır.'),
      P('Nəzarət: səlahiyyət, daxilolmalar və onların əlaqəsi',
        'İnvestor investisiya obyektinə nəzarət edir, əgər o, investisiya obyektində iştirakından dəyişən daxilolmalara məruz qalır və ya onlara hüquqa malikdir və investisiya obyekti üzərində səlahiyyətindən istifadə etməklə bu daxilolmalara təsir göstərmək imkanına malikdir (m. 6).',
        'Beləliklə, investor yalnız aşağıdakıların hamısına malik olduqda nəzarət edir (m. 7): investisiya obyekti üzərində səlahiyyət; investisiya obyektində iştirakından dəyişən daxilolmalara məruz qalma və ya onlara hüquq; daxilolmalarının məbləğinə təsir göstərmək üçün səlahiyyətindən istifadə etmək imkanı. Faktlar və şəraitlər bu üç elementdən birində dəyişiklik olduğunu göstərdikdə nəzarət yenidən qiymətləndirilir (m. 8).',
        'İnvestorun müvafiq fəaliyyətləri — investisiya obyektinin daxilolmalarına əhəmiyyətli təsir göstərən fəaliyyətləri — istiqamətləndirmək üçün mövcud hüquqları olduqda o, səlahiyyətə malikdir (m. 10). Səlahiyyət hüquqlardan yaranır; ən sadə halda bu, pay alətlərinin verdiyi səs hüquqlarıdır, mürəkkəb hallarda müqavilə razılaşmaları (m. 11). Yalnız əsaslı (substantive) hüquqlar nəzərə alınır; səlahiyyəti olan investor bu hüququnu hələ istifadə etməsə də, səlahiyyətə malikdir (m. 12, B22).',
        'Tətbiq təlimatında investorun səs hüquqlarının çoxluğuna malik olmadan da səlahiyyətə malik ola biləcəyi hallar izah olunur: digər səs sahibləri ilə müqavilə, digər müqavilə razılaşmalarından yaranan hüquqlar, investorun səs hüquqlarının ölçüsü və digər səs sahiblərinin dağınıqlığı (de-fakto nəzarət), potensial səs hüquqları (B38–B50).'),
      P('Uçot qaydaları və konsolidasiya prosedurları',
        'Əsas müəssisə oxşar şəraitdə oxşar əməliyyatlar üçün vahid uçot siyasətlərindən istifadə etməklə konsolidə edilmiş hesabatlar hazırlayır (m. 19). İnvestisiya obyektinin konsolidasiyası investorun ona nəzarəti əldə etdiyi tarixdən başlanır və nəzarəti itirdiyi tarixdə dayandırılır (m. 20).',
        'Konsolidasiya prosedurları (B86): əsas müəssisənin və törəmə müəssisələrinin oxşar aktiv, öhdəlik, kapital, gəlir, xərc və pul axını maddələri birləşdirilir; əsas müəssisənin hər törəmə müəssisəyə investisiyasının balans dəyəri ilə onun hər törəmə müəssisənin kapitalındakı payı qarşılıqlı əvəzləşdirilir (qudvil 3 №-li MHBS-ə uyğun); qrup daxilində əməliyyatlarla bağlı aktiv, öhdəlik, kapital, gəlir, xərc və pul axınları tam istisna edilir. Qrupdaxili əməliyyatlardan yaranan və aktivlərdə (məsələn, ehtiyatlarda və əsas vəsaitlərdə) tanınmış mənfəət və zərərlər tam istisna edilir.',
        'Hesabatlar eyni hesabat tarixinə hazırlanır. Tarixlər fərqlidirsə, törəmə müəssisə əlavə hesabat hazırlayır; bu mümkün olmadıqda fərq üç aydan çox olmamaq şərtilə əhəmiyyətli əməliyyatlara düzəlişlərlə ən son hesabatlardan istifadə edilir (B92–B93).'),
      P('Nəzarətetmə hüququ olmayan paylar',
        'Əsas müəssisə nəzarətetmə hüququ olmayan payları konsolidə edilmiş maliyyə vəziyyəti haqqında hesabatda kapitalın tərkibində, əsas müəssisənin sahiblərinin kapitalından ayrıca təqdim edir (m. 22). Mənfəət və ya zərər və sair məcmu gəlirin hər komponenti əsas müəssisənin sahiblərinə və nəzarətetmə hüququ olmayan paylara aid edilir; ümumi məcmu gəlir nəzarətetmə hüququ olmayan payların mənfi qalığı ilə nəticələnsə belə onlara aid edilir (B94).',
        'Əsas müəssisənin törəmə müəssisədəki payında nəzarətin itirilməsi ilə nəticələnməyən dəyişikliklər kapital əməliyyatlarıdır (yəni sahiblərlə əməliyyatlar) (m. 23); mənfəət və ya zərərdə gəlir və ya zərər tanınmır.'),
      P('Nəzarətin itirilməsi',
        'Əsas müəssisə törəmə müəssisə üzərində nəzarəti itirdikdə (m. 25, B98): keçmiş törəmə müəssisənin aktiv və öhdəliklərinin və nəzarətetmə hüququ olmayan payların tanınmasını dayandırır; keçmiş törəmə müəssisədə saxlanılan istənilən payı nəzarətin itirildiyi tarixdəki ədalətli dəyərlə tanıyır; nəzarətin itirilməsi ilə bağlı gəlir və ya zərəri mənfəət və ya zərərdə tanıyır; əvvəllər sair məcmu gəlirdə tanınmış məbləğləri, əgər əsas müəssisə müvafiq aktiv və ya öhdəlikləri birbaşa xaric etsəydi tələb olunacaq əsasda, mənfəət və ya zərərə yenidən təsnif edir və ya birbaşa bölüşdürülməmiş mənfəətə köçürür.'),
      P('İnvestisiya müəssisələri: konsolidasiya üzrə istisna',
        'İnvestisiya müəssisəsi investorlardan investisiya idarəetmə xidmətləri göstərmək üçün vəsait alan, investorlarına öz biznes məqsədinin yalnız kapital artımından, investisiya gəlirindən və ya hər ikisindən gəlir əldə etmək üçün vəsait qoymaq olduğunu bəyan edən və investisiyalarının nəticələrini ədalətli dəyər əsasında ölçən və qiymətləndirən müəssisədir (m. 27). İnvestisiya müəssisəsi törəmə müəssisələrini konsolidə etmir, onlara investisiyaları mənfəət və ya zərər vasitəsilə ədalətli dəyərlə ölçür (m. 31); investisiya xidmətləri göstərən törəmə müəssisələr istisnadır (m. 32).'),
      P('Azərbaycanda tətbiqi',
        '«Mühasibat uçotu haqqında» Qanuna əsasən bir və ya daha çox törəmə cəmiyyətə malik olan hər hansı ictimai əhəmiyyətli qurum hüquqi şəxs kimi hazırladığı hesabatdan əlavə MHBS-ə uyğun birləşdirilmiş (konsolidə edilmiş) maliyyə hesabatları tərtib etməlidir (Qanun, m. 8.2). Qurum aşağıdakı dörd şərti birlikdə yerinə yetirdikdə konsolidə hesabat tərtib etməmək hüququna malikdir (Qanun, m. 8.3): o, törəmə cəmiyyətdir və bütün mülkiyyətçiləri yekdilliklə razıdır; qiymətli kağızları açıq şəkildə satılmır; açıq bazara qiymətli kağızlar buraxmır; tabe olduğu əsas cəmiyyət MHBS-ə uyğun konsolidə hesabatları dərc etdirir.',
        'Konsolidə edilmiş hesabatlar hesabat ilindən sonrakı ilin iyunun 30-dan gec olmayaraq təqdim edilir (Qaydalar, b. 3.1).'),
      E('Ana şirkət törəmə müəssisəyə 60 000 AZN-ə mal satıb (maya dəyəri üzərinə 25% əlavə ilə). İlin sonunda malların yarısı törəmə müəssisənin anbarındadır.',
        'Mənfəət = 60 000 × 25/125 = 12 000.',
        'Reallaşmamış mənfəət = 12 000 × ½ = <b>6 000 AZN</b> — tam istisna edilir (B86).',
        'Konsolidasiya düzəlişi: gəlir −60 000, satışın maya dəyəri −54 000, ehtiyatlar −6 000.'),
      W('Nəzarət üç elementin birlikdə olmasıdır; 50%-dən çox səhm tək başına meyar deyil.',
        'Törəmə müəssisənin bütün aktiv və öhdəlikləri pay 60% olsa belə 100% birləşdirilir; azlıq payı ayrıca göstərilir.',
        'Nəzarət itirilmədən payın dəyişməsi kapital əməliyyatıdır — mənfəət və ya zərərə təsir etmir.'),
    ], 'ifrs10');

  add(36, 'ifrs11', 'Maliyyə Hesabatlarının Beynəlxalq Standartları', '11 №-li MHBS — Birgə razılaşmalar', T.G, ['MHBS11'],
    'Standart birgə nəzarət edilən razılaşmalarda iştirak payları olan müəssisələrin hesabatları üçün prinsipləri müəyyən edir: əvvəlcə razılaşmanın birgə razılaşma olub-olmadığı, sonra onun növü müəyyən edilir.',
    [
      P('Məqsəd və tətbiq sahəsi',
        'Standartın məqsədi birgə nəzarət edilən razılaşmalarda (birgə razılaşmalarda) iştirak paylarına malik müəssisələrin maliyyə hesabatları üçün prinsiplər müəyyən etməkdir (m. 1). Standart birgə razılaşmanın tərəfi olan bütün müəssisələrə tətbiq edilir (m. 3).'),
      P('Birgə razılaşmalar və birgə nəzarət',
        'Birgə razılaşma iki və ya daha çox tərəfin birgə nəzarətə malik olduğu razılaşmadır. Onun xüsusiyyətləri: tərəflər müqavilə razılaşması ilə bağlıdırlar; müqavilə razılaşması iki və ya daha çox tərəfə razılaşma üzərində birgə nəzarət verir (m. 4–5).',
        'Birgə nəzarət razılaşma üzərində nəzarətin müqavilə ilə razılaşdırılmış bölüşdürülməsidir və yalnız müvafiq fəaliyyətlər barədə qərarlar nəzarəti bölüşən tərəflərin yekdil razılığını tələb etdikdə mövcuddur (m. 7). Tərəflər əvvəlcə müqavilə razılaşmasının bütün tərəflərə və ya tərəflər qrupuna razılaşma üzərində kollektiv nəzarət verib-vermədiyini, sonra isə qərarların yekdil razılıq tələb edib-etmədiyini qiymətləndirir (m. 8–10).',
        'Birgə razılaşmanın bütün tərəfləri birgə nəzarətə malik olmaya bilər; birgə nəzarətə malik olmayan tərəf də birgə razılaşmada iştirak edə bilər (m. 11).'),
      P('Birgə razılaşmanın növləri',
        'Birgə razılaşma ya birgə əməliyyat, ya da birgə müəssisədir; növ tərəflərin hüquq və öhdəliklərindən asılıdır (m. 14–15).',
        'Birgə əməliyyat — razılaşma üzərində birgə nəzarətə malik tərəflərin razılaşmaya aid aktivlərə hüquqları və öhdəliklər üzrə vəzifələri olduğu birgə razılaşmadır. Birgə müəssisə — birgə nəzarətə malik tərəflərin razılaşmanın xalis aktivlərinə hüquqları olduğu birgə razılaşmadır (m. 15–16).',
        'Ayrıca vasitə (hüquqi şəxs) vasitəsilə qurulmayan birgə razılaşma birgə əməliyyatdır. Ayrıca vasitə vasitəsilə qurulmuş razılaşma isə vasitənin hüquqi forması, müqavilə şərtləri və digər faktlar nəzərə alınmaqla birgə əməliyyat və ya birgə müəssisə ola bilər (B16–B33).'),
      P('Uçot',
        'Birgə əməliyyat iştirakçısı birgə əməliyyatdakı iştirak payı ilə bağlı tanıyır (m. 20): öz aktivlərini, o cümlədən birgə saxlanılan aktivlərdəki payını; öz öhdəliklərini, o cümlədən birgə götürülmüş öhdəliklərdəki payını; birgə əməliyyatın məhsulundakı payının satışından gəlirini; birgə əməliyyatın məhsulunun satışından gəlirdəki payını; öz xərclərini, o cümlədən birgə çəkilmiş xərclərdəki payını.',
        'Birgə müəssisə iştirakçısı birgə müəssisədəki iştirak payını investisiya kimi tanıyır və onu 28 №-li MUBS-a uyğun iştirak payı metodu ilə uçota alır (m. 24). Proporsional konsolidasiya tətbiq edilmir.'),
      TB('Müqayisə',
        ['', 'Birgə əməliyyat', 'Birgə müəssisə'],
        ['Tərəflərin hüququ', 'Aktivlərə hüquq, öhdəliklər üzrə vəzifə', 'Xalis aktivlərə hüquq'],
        ['Uçot', 'Öz payı sətir-sətir', 'İştirak payı metodu (28 №-li MUBS)']),
      W('Birgə nəzarət — yekdil razılıq deməkdir. Ən böyük paya malik olmaq birgə nəzarət yaratmır.'),
    ]);

  add(37, 'ifrs12', 'Maliyyə Hesabatlarının Beynəlxalq Standartları', '12 №-li MHBS — Digər müəssisələrdə iştirak paylarının açıqlanması', T.N, ['MHBS12'],
    'Açıqlama standartıdır: digər müəssisələrdə iştirak paylarının xarakteri, riskləri və maliyyə təsirləri barədə məlumatı tələb edir. Proqramda məqsəd və tətbiq sahəsi tələb olunur.',
    [
      P('Məqsəd və onun yerinə yetirilməsi',
        'Standartın məqsədi müəssisədən istifadəçilərə aşağıdakıları qiymətləndirməyə imkan verən məlumatı açıqlamağı tələb etməkdir (m. 1): digər müəssisələrdəki iştirak paylarının xarakterini və onlarla bağlı riskləri; bu iştirak paylarının onun maliyyə vəziyyətinə, nəticələrinə və pul axınlarına təsirini.',
        'Məqsədə nail olmaq üçün müəssisə digər müəssisələrdə iştirak payının xarakterini, birgə razılaşmanın növünü və ya nəzarət, birgə nəzarət və ya əhəmiyyətli təsirə malik olduğunu müəyyən edərkən etdiyi əhəmiyyətli mühakimə və fərziyyələri, habelə törəmə müəssisələrdə, birgə razılaşmalarda, asılı müəssisələrdə və konsolidə edilməyən strukturlaşdırılmış müəssisələrdə iştirak payları barədə məlumatı açıqlayır (m. 2).'),
      P('Tətbiq sahəsi',
        'Standart törəmə müəssisədə, birgə razılaşmada (birgə əməliyyatda və ya birgə müəssisədə), asılı müəssisədə və ya konsolidə edilməyən strukturlaşdırılmış müəssisədə iştirak payı olan müəssisəyə tətbiq edilir (m. 5). Əmək fəaliyyəti başa çatdıqdan sonrakı mükafat planlarına, 27 №-li MUBS-a əsasən fərdi hesabatlara (bəzi istisnalarla) və 9 №-li MHBS-ə uyğun uçota alınan iştirak paylarının əksəriyyətinə tətbiq edilmir (m. 6).'),
    ]);

  add(38, 'ifrs13', 'Maliyyə Hesabatlarının Beynəlxalq Standartları', '13 №-li MHBS — Ədalətli dəyərin ölçülməsi', T.OT, ['MHBS13'],
    'Standart ədalətli dəyəri müəyyən edir, onun ölçülməsi üçün vahid çərçivə yaradır və açıqlamaları tələb edir. O, nəyin ədalətli dəyərlə ölçüləcəyini deyil, ədalətli dəyərin necə ölçüləcəyini müəyyən edir.',
    [
      P('Məqsəd və tətbiq sahəsi',
        'Standart ədalətli dəyəri müəyyən edir, ədalətli dəyərin ölçülməsi üçün vahid MHBS çərçivəsini yaradır və ədalətli dəyərin ölçülməsi barədə açıqlamaları tələb edir (m. 1). Ədalətli dəyər müəssisəyə xas deyil, bazara əsaslanan ölçmədir (m. 2).',
        'Standart digər MHBS ədalətli dəyərlə ölçməni və ya açıqlamanı tələb etdikdə və ya icazə verdikdə tətbiq edilir (m. 5). O, 2 №-li MHBS-in əhatə etdiyi pay alətləri əsasında ödəmələrə, icarə əməliyyatlarına, ehtiyatların mümkün xalis satış dəyərinə və 36 №-li MUBS-dakı istifadədə olan dəyərə tətbiq edilmir (m. 6).'),
      P('Ədalətli dəyər anlayışı',
        'Ədalətli dəyər ölçülmə tarixində bazar iştirakçıları arasında adi əməliyyatda aktivin satışından alınacaq və ya öhdəliyin ötürülməsi üçün ödəniləcək qiymətdir (m. 9) — yəni çıxış qiymətidir.',
        'Aktiv və ya öhdəlik. Ölçülmə konkret aktiv və ya öhdəlik üçün aparılır; müəssisə bazar iştirakçılarının qiymət müəyyən edərkən nəzərə alacağı xüsusiyyətləri (vəziyyəti, yeri, satışa və ya istifadəyə məhdudiyyətlər) nəzərə alır (m. 11).',
        'Əməliyyat. Ədalətli dəyər aktivin satışı və ya öhdəliyin ötürülməsinin aktiv və ya öhdəlik üçün əsas bazarda, əsas bazar olmadıqda isə ən əlverişli bazarda baş verdiyi fərziyyəsinə əsaslanır (m. 16). Əsas bazar aktiv və ya öhdəlik üçün ən böyük həcm və fəallığa malik bazardır (Əlavə A).',
        'Bazar iştirakçıları. Ədalətli dəyər bazar iştirakçılarının iqtisadi maraqlarına uyğun hərəkət etdikləri fərziyyəsi ilə ölçülür (m. 22).',
        'Qiymət. Ədalətli dəyəri ölçmək üçün istifadə olunan qiymət əməliyyat xərcləri ilə düzəldilmir; əməliyyat xərcləri aktiv və ya öhdəliyin xüsusiyyəti deyil. Nəqliyyat xərcləri isə, yer aktivin xüsusiyyətidirsə, qiymətdən çıxılır (m. 25–26).'),
      P('Qeyri-maliyyə aktivlərinə tətbiq',
        'Qeyri-maliyyə aktivinin ədalətli dəyərinin ölçülməsi bazar iştirakçısının aktivdən ən yüksək və ən yaxşı istifadəsi və ya onu ən yüksək və ən yaxşı istifadə edəcək başqa bazar iştirakçısına satması yolu ilə iqtisadi səmərə yaratmaq qabiliyyətini nəzərə alır (m. 27). Ən yüksək və ən yaxşı istifadə fiziki cəhətdən mümkün, hüquqi cəhətdən icazə verilən və maliyyə baxımından məqsədəuyğun istifadədir (m. 28). Müəssisənin aktivi cari istifadəsi, başqa sübut olmadıqda, ən yüksək və ən yaxşı istifadə hesab edilir (m. 29).'),
      P('İlkin tanınma zamanı ədalətli dəyər',
        'Əməliyyat qiyməti aktivin əldə edilməsi üçün ödənilən giriş qiymətidir, ədalətli dəyər isə çıxış qiymətidir (m. 57). Bir çox hallarda əməliyyat qiyməti ədalətli dəyərə bərabərdir, lakin, məsələn, əlaqəli tərəflər arasında əməliyyatda və ya məcburi satışda fərqli ola bilər (m. 58, B4).'),
      P('Qiymətləndirmə üsulları və ədalətli dəyər iyerarxiyası',
        'Müəssisə şəraitə uyğun, kifayət qədər məlumat mövcud olan və müşahidə edilə bilən resurslardan maksimum, müşahidə edilə bilməyənlərdən minimum istifadə edən qiymətləndirmə üsullarından istifadə edir (m. 61). Üç geniş yanaşma var (m. 62): bazar yanaşması (eyni və ya müqayisə edilə bilən aktivlərlə əməliyyatların qiymətləri); xərc yanaşması (aktivin xidmət gücünü əvəz etmək üçün hazırda tələb olunan məbləğ — cari əvəzləmə dəyəri); gəlir yanaşması (gələcək pul axınlarının, gəlir və xərclərin vahid cari məbləğə çevrilməsi — diskontlaşdırma).',
        'Ədalətli dəyər iyerarxiyası qiymətləndirmə üsullarına resursları üç səviyyəyə bölür (m. 72): 1-ci səviyyə — müəssisənin ölçülmə tarixində çıxışı olduğu eyni aktiv və ya öhdəliklər üçün fəal bazarlarda düzəldilməmiş kotirovka qiymətləri (m. 76); 2-ci səviyyə — 1-ci səviyyəyə daxil edilən kotirovka qiymətlərindən başqa, birbaşa və ya dolayı müşahidə edilə bilən resurslar, məsələn, oxşar aktivlərin qiymətləri, faiz dərəcələri əyriləri (m. 81–82); 3-cü səviyyə — müşahidə edilə bilməyən resurslar (m. 86). Ən yüksək prioritet 1-ci səviyyəyə, ən aşağı 3-cü səviyyəyə verilir.',
        'Tələb və təklif qiymətləri olduqda ədalətli dəyəri şəraitdə ən yaxşı əks etdirən qiymətdən istifadə edilir; orta bazar qiymətindən istifadə edilə bilər (m. 70–71).'),
      E('Aktiv iki bazarda satıla bilər. A bazarı (müəssisə üçün əsas bazar): qiymət 26, əməliyyat xərcləri 3, nəqliyyat 2. B bazarı: qiymət 25, əməliyyat xərcləri 1, nəqliyyat 2.',
        'Əsas bazar mövcud olduğundan ədalətli dəyər A bazarında ölçülür (m. 16).',
        'Əməliyyat xərcləri çıxılmır, nəqliyyat xərcləri çıxılır (m. 25–26): ədalətli dəyər = 26 − 2 = <b>24</b>.'),
      W('Ədalətli dəyər giriş deyil, çıxış qiymətidir.', 'Əməliyyat xərcləri ədalətli dəyərə təsir etmir, nəqliyyat xərcləri isə edir.'),
    ]);

  add(39, 'ifrs14', 'Maliyyə Hesabatlarının Beynəlxalq Standartları', '14 №-li MHBS — Təxirə salınmış tarif düzəlişləri üzrə hesablar', T.N, ['MHBS14'],
    'Tarifləri tənzimlənən fəaliyyətlə məşğul olan və MHBS-i ilk dəfə tətbiq edən müəssisələr üçün müvəqqəti standartdır. Proqramda məqsəd və tətbiq sahəsi tələb olunur.',
    [
      P('Məqsəd və tətbiq sahəsi',
        'Standartın məqsədi tarifləri tənzimlənən fəaliyyətlə məşğul olan müəssisə tərəfindən təxirə salınmış tarif düzəlişləri üzrə hesabların qalıqlarına dair hesabat tələblərini müəyyən etməkdir (m. 1). Tarif tənzimlənməsi elə çərçivədir ki, orada mal və ya xidmətlərin qiyməti tənzimləyici orqan tərəfindən müəyyən edilir (məsələn, elektrik enerjisi, qaz, su təchizatı).',
        'Müəssisə standartı yalnız o halda tətbiq edə bilər ki, o, MHBS-i ilk dəfə tətbiq edir, tarifləri tənzimlənən fəaliyyətlə məşğul olur və əvvəlki uçot qaydalarına əsasən belə qalıqları tanıyırdı (m. 5). Standart əvvəlki uçot siyasətinin davam etdirilməsinə imkan verir, lakin belə qalıqların digər maddələrdən ayrıca təqdim edilməsini tələb edir (m. 20–23).'),
    ]);

  add(40, 'ifrs15', 'Maliyyə Hesabatlarının Beynəlxalq Standartları', '15 №-li MHBS — Müştərilərlə müqavilələr üzrə gəlirlər', T.R, ['MHBS15', 'UCOT'],
    'Standartın əsas prinsipi: müəssisə vəd edilmiş mal və ya xidmətlərin müştərilərə ötürülməsini, həmin mal və ya xidmətlər müqabilində almağa hüququ olduğunu gözlədiyi ödənişi əks etdirən məbləğdə gəlir kimi tanıyır.',
    [
      P('Məqsəd və onun yerinə yetirilməsi',
        'Standartın məqsədi müştəri ilə müqavilədən yaranan gəlirin və pul axınlarının xarakteri, məbləği, vaxtı və qeyri-müəyyənliyi barədə istifadəçilərə faydalı məlumat vermək üçün prinsiplər müəyyən etməkdir (m. 1). Əsas prinsipə uyğun olaraq müəssisə aşağıdakı addımları tətbiq edir (m. 2, IN7): 1) müştəri ilə müqavilənin müəyyən edilməsi; 2) müqavilədəki icra öhdəliklərinin müəyyən edilməsi; 3) əməliyyat qiymətinin müəyyən edilməsi; 4) əməliyyat qiymətinin icra öhdəliklərinə bölüşdürülməsi; 5) müəssisə icra öhdəliyini yerinə yetirdikdə (və ya yerinə yetirdikcə) gəlirin tanınması.'),
      P('Addım 1 — Müqavilənin müəyyən edilməsi',
        'Müəssisə müştəri ilə müqaviləni yalnız aşağıdakı meyarların hamısı ödənildikdə uçota alır (m. 9): tərəflər müqaviləni təsdiq edib və öhdəliklərini yerinə yetirməyə sadiqdirlər; müəssisə hər tərəfin ötürüləcək mal və ya xidmətlərə dair hüquqlarını müəyyən edə bilir; ödəniş şərtlərini müəyyən edə bilir; müqavilənin kommersiya mahiyyəti var; müəssisənin hüququ çatacaq ödənişi toplaması ehtimal olunur.',
        'Müqavilələrin birləşdirilməsi: eyni vaxtda və ya təxminən eyni vaxtda eyni müştəri ilə bağlanmış iki və ya daha çox müqavilə vahid kommersiya məqsədi ilə danışıqlar aparıldıqda, bir müqavilə üzrə ödəniş digərinin qiymətindən və ya icrasından asılı olduqda və ya vəd edilmiş mallar vahid icra öhdəliyidirsə birləşdirilir (m. 17).',
        'Müqaviləyə düzəlişlər: düzəliş, əgər fərqli mal və ya xidmətlərin əlavə edilməsi hesabına müqavilənin həcmi artır və qiymət onların xüsusi satış qiymətini əks etdirən məbləğdə artırsa, ayrıca müqavilə kimi uçota alınır (m. 20).'),
      P('Addım 2 — İcra öhdəliklərinin müəyyən edilməsi',
        'Müqavilənin bağlanması zamanı müəssisə müştəriyə vəd edilmiş mal və ya xidmətləri qiymətləndirir və müştəriyə aşağıdakılardan birini ötürmək üzrə hər bir vədi icra öhdəliyi kimi müəyyən edir (m. 22): fərqli mal və ya xidmət; mahiyyətcə eyni olan və müştəriyə eyni qaydada ötürülən bir sıra fərqli mal və ya xidmətlər.',
        'Mal və ya xidmət fərqlidir, əgər hər iki meyar ödənilir (m. 27): müştəri mal və ya xidmətdən özlüyündə və ya ona asanlıqla mövcud olan digər resurslarla birlikdə fayda əldə edə bilir; müəssisənin vədi müqavilədəki digər vədlərdən ayrıca müəyyən edilə bilir.'),
      P('Addım 3 — Əməliyyat qiymətinin müəyyən edilməsi',
        'Əməliyyat qiyməti müəssisənin vəd edilmiş mal və ya xidmətlərin ötürülməsi müqabilində almağa hüququ olduğunu gözlədiyi ödəniş məbləğidir; üçüncü tərəflərin adından toplanan məbləğlər (məsələn, satış vergiləri) buraya daxil deyil (m. 47). Qiymət müəyyən edilərkən dəyişkən ödəniş, mühüm maliyyə komponenti, qeyri-pul ödənişi və müştəriyə ödənilməli vəsaitlər nəzərə alınır (m. 48).',
        'Dəyişkən ödəniş məbləği (güzəştlər, endirimlər, bonuslar, cərimələr, qaytarma hüququ) iki metoddan biri ilə — gözlənilən dəyər və ya ən ehtimal olunan məbləğ — qiymətləndirilir (m. 50–53). O, əməliyyat qiymətinə yalnız qeyri-müəyyənlik aradan qalxdıqda tanınmış məcmu gəlirin əhəmiyyətli dərəcədə geri qaytarılmasının yüksək ehtimallı olmadığı həddə daxil edilir (m. 56).',
        'Müqavilədə mühüm maliyyə komponenti olduqda müəssisə ödəniş məbləğini pulun zaman dəyərinin təsirinə görə düzəldir; ödəniş ilə ötürmə arasındakı müddət bir ildən çox deyilsə, düzəliş edilməyə bilər (m. 60, 63). Qeyri-pul ödənişi ədalətli dəyərlə ölçülür (m. 66). Müştəriyə ödənilməli vəsaitlər, fərqli mal və ya xidmət müqabilində olmadıqda, əməliyyat qiymətinin azalması kimi uçota alınır (m. 70).'),
      P('Addım 4 — Əməliyyat qiymətinin bölüşdürülməsi',
        'Əməliyyat qiyməti hər icra öhdəliyinə müəssisənin vəd edilmiş mal və ya xidmətin ötürülməsi müqabilində almağa hüququ olduğunu gözlədiyi məbləğdə bölüşdürülür (m. 73). Bunun üçün qiymət icra öhdəliklərinə nisbi xüsusi satış qiymətləri əsasında bölüşdürülür (m. 74, 76). Xüsusi satış qiyməti birbaşa müşahidə edilmirsə, o, düzəldilmiş bazar qiymətləndirməsi, gözlənilən xərc üstəgəl marja və ya qalıq yanaşması ilə qiymətləndirilir (m. 79).',
        'Güzəştin bölüşdürülməsi: güzəşt, adətən, bütün icra öhdəliklərinə mütənasib bölüşdürülür, yalnız müəyyən şərtlər ödənildikdə bir və ya bir neçə öhdəliyə aid edilir (m. 81–82). Əməliyyat qiymətində sonrakı dəyişikliklər müqavilənin bağlanmasında olduğu kimi eyni əsasda bölüşdürülür (m. 88).'),
      P('Addım 5 — İcra öhdəliklərinin yerinə yetirilməsi',
        'Müəssisə vəd edilmiş mal və ya xidməti (aktivi) müştəriyə ötürməklə icra öhdəliyini yerinə yetirdikdə (və ya yerinə yetirdikcə) gəliri tanıyır. Aktiv müştəri onun üzərində nəzarəti əldə etdikdə ötürülür (m. 31). Nəzarət — aktivin istifadəsini istiqamətləndirmək və ondan qalan faydaların əksəriyyətini əldə etmək qabiliyyətidir (m. 33).',
        'Dövr ərzində yerinə yetirilən icra öhdəlikləri. Müəssisə mal və ya xidmətə nəzarəti dövr ərzində ötürür və gəliri dövr ərzində tanıyır, əgər aşağıdakı meyarlardan biri ödənilirsə (m. 35): müştəri müəssisənin icrasının təmin etdiyi faydaları eyni vaxtda alır və istehlak edir; müəssisənin icrası müştərinin nəzarət etdiyi aktivi yaradır və ya təkmilləşdirir; müəssisənin icrası onun üçün alternativ istifadəsi olan aktiv yaratmır və müəssisənin bu günədək yerinə yetirilmiş işə görə ödəniş almaq üçün hüquqi qüvvəyə malik hüququ var.',
        'İcra öhdəliyinin yerinə yetirilmə səviyyəsi nəticə metodları (görülmüş işin müayinəsi, əldə edilmiş nəticələr, ötürülmüş vahidlər) və ya resurs metodları (çəkilmiş xərclər, sərf olunmuş iş saatları) ilə ölçülür (m. 39–41, B14–B19).',
        'Konkret vaxtda yerinə yetirilən icra öhdəlikləri. Meyarlar ödənilmədikdə öhdəlik konkret vaxtda yerinə yetirilir. Nəzarətin ötürülməsinin göstəricilərinə daxildir (m. 38): müəssisənin aktiv üçün ödəniş almaq üçün cari hüququ; müştərinin aktivə hüquqi mülkiyyət hüququ; müəssisənin aktivin fiziki sahibliyini ötürməsi; müştərinin aktivin mülkiyyəti ilə bağlı əhəmiyyətli risk və faydalara malik olması; müştərinin aktivi qəbul etməsi.'),
      P('Müqavilə üzrə xərclər və qalıqlar',
        'Müştəri ilə müqavilənin bağlanmasına çəkilən əlavə xərclər (məsələn, satış komissiyası) müəssisə onları bərpa etməyi gözləyirsə aktiv kimi tanınır; amortizasiya müddəti bir ildən çox deyilsə, praktik vasitə kimi xərc kimi tanına bilər (m. 91, 94). Müqavilənin icrası ilə bağlı xərclər, başqa standartın əhatəsinə düşmürsə və müəyyən meyarlara cavab verirsə, aktiv kimi tanınır (m. 95). Bu aktivlər sistematik əsasda amortizasiya edilir və dəyərsizləşməyə yoxlanılır (m. 99, 101).',
        'Tərəflərdən biri müqaviləni icra etdikdə müəssisə müqaviləni müqavilə aktivi və ya müqavilə öhdəliyi kimi təqdim edir (m. 105). Müştəri ödəniş etdikdə və ya müəssisənin şərtsiz ödəniş hüququ yarandıqda, lakin mal və ya xidmət ötürülməzdən əvvəl, müəssisə müqavilə öhdəliyi tanıyır (m. 106). Müəssisə ödənişdən əvvəl mal və ya xidməti ötürübsə və ödəniş hüququ zamanın keçməsindən başqa şərtdən asılıdırsa, müqavilə aktivi, şərtsiz hüquq olduqda isə debitor borcu tanınır (m. 107–108).',
        'Açıqlamalarda gəlirlərin təfsilatı, müqavilə qalıqları, icra öhdəlikləri və qalan icra öhdəliklərinə bölüşdürülmüş əməliyyat qiyməti açıqlanır (m. 114–122).'),
      P('Xüsusi hallar (Tətbiq təlimatı)',
        'Geri qaytarılma hüququ ilə satış: müəssisə qaytarılması gözlənilməyən məhsullar üzrə gəlir, gözlənilən qaytarmalar üzrə geri ödəniş öhdəliyi və qaytarılacaq məhsulları bərpa etmək hüququ üzrə aktiv tanıyır (B21).',
        'Zəmanətlər: müştəri zəmanəti ayrıca almaq imkanına malikdirsə və ya zəmanət razılaşdırılmış spesifikasiyaya uyğunluq zəmanətindən əlavə xidmət təmin edirsə, bu, ayrıca icra öhdəliyidir; əks halda zəmanət 37 №-li MUBS-a uyğun uçota alınır (B28–B33).',
        'Əsas tərəfin və vasitəçinin vəzifəsi: müəssisə mal və ya xidmət müştəriyə ötürülməzdən əvvəl ona nəzarət edirsə, əsas tərəfdir və gəliri ümumi məbləğdə tanıyır; nəzarət etmirsə, vasitəçidir (agentdir) və gəliri komissiya (haqq) məbləğində tanıyır (B34–B38).',
        'Konsiqnasiya razılaşmaları: məhsulu satış üçün vasitəçiyə (dilerə) çatdıran müəssisə, vasitəçi məhsul üzərində nəzarəti əldə etməyibsə, çatdırılma zamanı gəlir tanımır (B77–B78).'),
      E('Paket 900 AZN-ə satılır: mal (xüsusi satış qiyməti 600 AZN) və bir illik xidmət (xüsusi satış qiyməti 400 AZN).',
        'Xüsusi satış qiymətlərinin cəmi 1 000; güzəşt 100 bütün öhdəliklərə mütənasib bölünür (m. 81).',
        'Mal: 900 × 600/1 000 = <b>540 AZN</b> — nəzarət ötürüldükdə, konkret vaxtda.',
        'Xidmət: 900 × 400/1 000 = <b>360 AZN</b> — 12 ay ərzində bərabər (m. 35).'),
      J('Azərbaycanda tətbiqi — hesablar planı',
        '<b>601</b> Satış · <b>602</b> Satılmış malların qaytarılması və ucuzlaşdırılması · <b>603</b> Verilmiş güzəştlər',
        '<b>211</b> Alıcılar və sifarişçilərin qısamüddətli debitor borcları · <b>543</b> Alınmış qısamüddətli avanslar (müqavilə öhdəliyi) · <b>203/215/536</b> Tikinti müqavilələri üzrə hesablar'),
      W('Faktura yazılması və ya pulun alınması gəlirin tanınma anını müəyyən etmir — nəzarətin ötürülməsi müəyyən edir.',
        'Vasitəçi yalnız komissiyanı gəlir kimi tanıyır.'),
    ], 'ifrs15');

  add(41, 'ifrs16', 'Maliyyə Hesabatlarının Beynəlxalq Standartları', '16 №-li MHBS — İcarələr', T.L, ['MHBS16', 'UCOT'],
    'Standart icarələrin tanınması, ölçülməsi, təqdimatı və açıqlanması prinsiplərini müəyyən edir. İcarəçi üçün vahid model tətbiq edilir: demək olar ki, bütün icarələr üzrə istifadə hüququ aktivi və icarə öhdəliyi tanınır. Rəsmi tərcümədə icarəyə verən tərəf "icarədar" adlanır.',
    [
      P('Məqsəd və tətbiq sahəsi',
        'Standartın məqsədi icarəçilərin və icarədarların bu əməliyyatları düzgün əks etdirən məlumatı təqdim etməsini təmin etməkdir (m. 1). Standart bütün icarələrə, o cümlədən sub-icarədəki istifadə hüququ aktivlərinə tətbiq edilir; istisnalar faydalı qazıntıların kəşfiyyatı və istifadəsi üzrə icarələr, bioloji aktivlərin icarəsi, xidmət konsessiyası razılaşmaları, icarədarın verdiyi əqli mülkiyyət lisenziyaları və bəzi digər hüquqlardır (m. 3).'),
      P('Tanınma üzrə istisnalar',
        'İcarəçi aşağıdakılar üçün istifadə hüququ aktivi və icarə öhdəliyi tanımamağı seçə bilər (m. 5): qısamüddətli icarələr (icarə müddəti 12 ay və ya daha az olan və alış opsionu olmayan icarələr); əsas aktivi aşağı dəyərə malik olan icarələr. Bu halda icarə ödənişləri icarə müddəti ərzində düz xətt və ya digər sistematik əsasda xərc kimi tanınır (m. 6). Qısamüddətli icarə üçün seçim əsas aktiv sinfi üzrə, aşağı dəyərli aktiv üçün isə hər icarə üzrə edilir (m. 8). Aşağı dəyər aktivin yeni olduqdakı dəyərinə əsasən mütləq ifadədə qiymətləndirilir (B3–B5).'),
      P('İcarənin müəyyən edilməsi',
        'Müqavilənin bağlanması zamanı müəssisə onun icarə olub-olmadığını və ya icarəni ehtiva edib-etmədiyini qiymətləndirir. Müqavilə müəyyən edilmiş aktivin istifadəsinə nəzarət hüququnu müəyyən müddətə ödəniş müqabilində ötürürsə, icarədir (m. 9).',
        'Bunun üçün müştəri istifadə müddəti ərzində həm müəyyən edilmiş aktivin istifadəsindən iqtisadi faydaların əsas hissəsini almaq hüququna, həm də onun istifadəsini istiqamətləndirmək hüququna malik olmalıdır (B9). Aktiv adətən müqavilədə açıq və ya dolayı göstərilməklə müəyyən edilir; lakin təchizatçının istifadə müddəti ərzində aktivi əvəz etmək üçün əsaslı hüququ varsa, müştəri müəyyən edilmiş aktivdən istifadə hüququna malik deyil (B13–B14).',
        'Müqavilənin komponentlərinin ayrılması: icarə komponentini ehtiva edən müqavilədə hər icarə komponenti qeyri-icarə komponentlərindən (məsələn, texniki xidmətdən) ayrıca uçota alınır; icarəçi praktik vasitə kimi ayırmamağı seçə bilər (m. 12, 15).',
        'İcarə müddəti icarənin ləğv edilə bilməyən dövrüdür, üstəgəl icarəçinin istifadə edəcəyinə əsaslı əminliyi olan uzatma opsionu və istifadə etməyəcəyinə əsaslı əminliyi olan xitam opsionu ilə əhatə olunan dövrlər (m. 18).'),
      P('İcarəçi: ilkin tanınma və ölçmə',
        'İcarənin başlanma tarixində icarəçi istifadə hüququ aktivini və icarə öhdəliyini tanıyır (m. 22).',
        'İstifadə hüququ aktivi ilkin dəyərlə ölçülür; ona daxildir (m. 23–24): icarə öhdəliyinin ilkin ölçülmüş məbləği; başlanma tarixində və ya ondan əvvəl edilmiş icarə ödənişləri, alınmış icarə stimulları çıxılmaqla; icarəçinin çəkdiyi ilkin birbaşa xərclər; əsas aktivin sökülməsi, köçürülməsi və yerin bərpası üzrə icarəçinin çəkəcəyi xərclərin qiymətləndirilməsi.',
        'İcarə öhdəliyi başlanma tarixində həmin tarixdə ödənilməmiş icarə ödənişlərinin diskontlaşdırılmış dəyəri ilə ölçülür. Ödənişlər icarədə nəzərdə tutulan faiz dərəcəsi ilə, bu dərəcə asanlıqla müəyyən edilə bilmirsə, icarəçinin əlavə borclanma faiz dərəcəsi ilə diskontlaşdırılır (m. 26).',
        'İcarə öhdəliyinə daxil edilən ödənişlər (m. 27): sabit ödənişlər, alınacaq icarə stimulları çıxılmaqla; indeksdən və ya dərəcədən asılı olan dəyişkən ödənişlər (başlanma tarixindəki indeks və ya dərəcə ilə); qalıq dəyər zəmanətləri üzrə ödənilməsi gözlənilən məbləğlər; icarəçinin istifadə edəcəyinə əsaslı əminliyi olan alış opsionunun qiyməti; icarə müddəti xitam opsionunun istifadəsini əks etdirirsə, xitam cərimələri. İndeks və ya dərəcədən asılı olmayan dəyişkən ödənişlər (məsələn, satışdan asılı ödənişlər) öhdəliyə daxil edilmir və yarandıqları dövrdə mənfəət və ya zərərdə tanınır (m. 38).'),
      P('İcarəçi: sonrakı ölçmə (ilkin dəyər modeli)',
        'İstifadə hüququ aktivi ilkin dəyərdən yığılmış amortizasiya və qiymətdən düşmə zərərləri çıxılmaqla ölçülür və icarə öhdəliyinin yenidən ölçülməsinə görə düzəldilir (m. 30). Amortizasiya 16 №-li MUBS-a uyğun hesablanır (m. 31). İcarə əsas aktivin mülkiyyətini icarə müddətinin sonunda icarəçiyə ötürürsə və ya alış opsionunun icra ediləcəyi gözlənilirsə, aktiv onun istismar müddəti ərzində, əks halda — istismar müddəti və icarə müddətindən qısası ərzində amortizasiya edilir (m. 32).',
        'İcarə öhdəliyi faizi əks etdirmək üçün balans dəyərini artırmaqla, edilmiş ödənişləri əks etdirmək üçün azaltmaqla və yenidən qiymətləndirmə və düzəlişləri əks etdirmək üçün yenidən ölçülür (m. 36). Hər dövr üzrə faiz öhdəliyin qalığına sabit dövri faiz dərəcəsi tətbiq etməklə hesablanır (m. 37).',
        'İcarə öhdəliyinin yenidən qiymətləndirilməsi: icarə müddəti və ya alış opsionunun qiymətləndirilməsi dəyişdikdə öhdəlik yenidən işlənmiş diskont dərəcəsi ilə, qalıq dəyər zəmanəti üzrə gözlənilən məbləğlər və ya indeks və dərəcə dəyişdikdə isə dəyişməz diskont dərəcəsi ilə yenidən ölçülür; düzəliş istifadə hüququ aktivinə edilir (m. 39–43).'),
      E('İcarə: 3 il, hər ilin sonunda 10 000 AZN ödəniş, icarədə nəzərdə tutulan faiz dərəcəsi 10%.',
        'İcarə öhdəliyi = 10 000 × (0,9091 + 0,8264 + 0,7513) = <b>24 869 AZN</b> (m. 26).',
        '1-ci il: faiz 2 487 (m. 37); qalıq = 24 869 + 2 487 − 10 000 = 17 356.',
        'İstifadə hüququ aktivinin illik amortizasiyası = 24 869 / 3 = 8 290 (m. 32).',
        'Ödənişlər ilin əvvəlində olarsa, birinci ödəniş öhdəliyə daxil edilmir: öhdəlik = 10 000 × (0,9091 + 0,8264) = 17 355; aktiv = 17 355 + 10 000 = 27 355 (m. 24).'),
      P('İcarədar: icarə növlərinin təsnifatı',
        'İcarədar hər icarəni ya əməliyyat icarəsi, ya da maliyyə icarəsi kimi təsnif edir (m. 61). Əsas aktivin mülkiyyətinə aid risk və faydaların əsas hissəsini ötürən icarə maliyyə icarəsidir, ötürməyən icarə isə əməliyyat icarəsidir (m. 62). Təsnifat formadan çox əməliyyatın mahiyyətindən asılıdır.',
        'Maliyyə icarəsi kimi təsnifata adətən gətirib çıxaran hallar (m. 63): icarə mülkiyyət hüququnu icarə müddətinin sonunda icarəçiyə ötürür; icarəçinin aktivi ədalətli dəyərdən kifayət qədər aşağı qiymətə almaq opsionu var və onun icra ediləcəyinə əsaslı əminlik var; icarə müddəti əsas aktivin iqtisadi istismar müddətinin əsas hissəsini əhatə edir; icarə ödənişlərinin diskontlaşdırılmış dəyəri əsas aktivin ədalətli dəyərinin demək olar ki, hamısına bərabərdir; əsas aktiv xüsusi xarakterlidir və yalnız icarəçi onu əsaslı dəyişikliklər olmadan istifadə edə bilər.'),
      P('İcarədar: maliyyə və əməliyyat icarəsi',
        'Maliyyə icarəsi: başlanma tarixində icarədar maliyyə icarəsi üzrə saxlanılan aktivləri icarə üzrə xalis investisiya qoyuluşuna bərabər məbləğdə debitor borcu kimi tanıyır (m. 67). Xalis investisiya qoyuluşunun ölçülməsinə daxil edilən icarə ödənişləri sabit ödənişlər, indeksdən asılı dəyişkən ödənişlər, qalıq dəyər zəmanətləri, alış opsionunun qiyməti və xitam cərimələridir (m. 70). Sonradan icarədar maliyyə gəlirini icarə üzrə xalis investisiya qoyuluşuna sabit dövri gəlirlilik dərəcəsini əks etdirən əsasda tanıyır (m. 75).',
        'İstehsalçı və ya diler qismində çıxış edən icarədar başlanma tarixində gəliri (əsas aktivin ədalətli dəyəri və ya ondan aşağıdırsa, icarə ödənişlərinin bazar faizi ilə diskontlaşdırılmış dəyəri), satışın maya dəyərini və satışdan mənfəət və ya zərəri tanıyır (m. 71).',
        'Əməliyyat icarəsi: icarədar əməliyyat icarəsi üzrə ödənişləri düz xətt və ya digər sistematik əsasda gəlir kimi tanıyır (m. 81). Əsas aktiv icarədarın balansında qalır və amortizasiya edilir (m. 84).',
        'İcarə müqaviləsində dəyişikliklər həm icarəçi, həm də icarədar üçün xüsusi qaydalarla — ayrıca icarə kimi və ya mövcud icarənin yenidən ölçülməsi kimi — uçota alınır (m. 44–46, 79–80, 87).'),
      P('Satış və geriyə icarə əməliyyatları',
        'Müəssisə (satıcı-icarəçi) aktivi başqa müəssisəyə (alıcı-icarədara) ötürür və onu geri icarəyə götürürsə, hər iki tərəf aktivin ötürülməsinin 15 №-li MHBS-ə əsasən satış olub-olmadığını qiymətləndirir (m. 98–99).',
        'Ötürmə satışdırsa, satıcı-icarəçi geri icarədən yaranan istifadə hüququ aktivini aktivin əvvəlki balans dəyərinin saxlanılan istifadə hüququna aid hissəsi ilə ölçür və yalnız alıcı-icarədara ötürülmüş hüquqlara aid gəlir və ya zərəri tanıyır (m. 100). Ötürmə satış deyilsə, satıcı-icarəçi ötürülmüş aktivi tanımağa davam edir və alınan vəsaitə bərabər maliyyə öhdəliyi tanıyır; alıcı-icarədar isə maliyyə aktivi tanıyır (m. 103).'),
      P('Sub-icarənin təsnifləşdirilməsi',
        'Aralıq icarədar sub-icarəni maliyyə və ya əməliyyat icarəsi kimi əsas aktivə deyil, baş icarədən yaranan istifadə hüququ aktivinə istinadla təsnif edir; baş icarə qısamüddətli icarədirsə və müəssisə istisnanı tətbiq edibsə, sub-icarə əməliyyat icarəsi kimi təsnif edilir (B58).'),
      J('Azərbaycanda tətbiqi — hesablar planı',
        '<b>406</b> Maliyyə icarəsi üzrə uzunmüddətli öhdəliklər · <b>535</b> İcarə üzrə qısamüddətli kreditor borcları · <b>174/214</b> İcarə üzrə uzunmüddətli/qısamüddətli debitor borcları',
        'İcarəçi: <b>Dt</b> istifadə hüququ aktivi (TTA bölməsində) — <b>Kt 406/535</b>; faiz: <b>Dt 751</b> Maliyyə xərcləri — <b>Kt 406/535</b>'),
      W('İstifadə hüququ aktivi, mülkiyyət keçmirsə, icarə müddəti ilə istismar müddətinin qısası ərzində amortizasiya edilir.',
        'Satışdan asılı dəyişkən ödənişlər icarə öhdəliyinə daxil edilmir.',
        'İcarədar üçün maliyyə/əməliyyat icarəsi bölgüsü qalır, icarəçi üçün isə yoxdur.'),
    ], 'ifrs16');

  add(42, 'ifrs17', 'Maliyyə Hesabatlarının Beynəlxalq Standartları', '17 №-li MHBS — Sığorta müqavilələri', T.N, ['MHBS17'],
    'Standart sığorta müqavilələrinin tanınması, ölçülməsi, təqdimatı və açıqlanması prinsiplərini müəyyən edir. Proqramda məqsəd və tətbiq sahəsi tələb olunur.',
    [
      P('Məqsəd',
        'Standartın məqsədi müəssisənin bu müqavilələri düzgün əks etdirən münasib məlumat təqdim etməsini təmin etməkdir; bu məlumat istifadəçilərə standartın əhatə etdiyi müqavilələrin müəssisənin maliyyə vəziyyətinə, nəticələrinə və pul axınlarına təsirini qiymətləndirməyə imkan verir (m. 1).'),
      P('Tətbiq sahəsi',
        'Müəssisə standartı aşağıdakılara tətbiq edir (m. 3): buraxdığı sığorta müqavilələrinə, o cümlədən təkrarsığorta müqavilələrinə; saxladığı təkrarsığorta müqavilələrinə; sığorta müqavilələri də buraxması şərtilə buraxdığı diskresion iştirak xüsusiyyətli investisiya müqavilələrinə.',
        'Sığorta müqaviləsi bir tərəfin (sığortaçının) digər tərəfdən (sığortalıdan) əhəmiyyətli sığorta riskini qəbul etdiyi və müəyyən qeyri-müəyyən gələcək hadisə sığortalıya mənfi təsir göstərdikdə ona kompensasiya ödəməyə razılaşdığı müqavilədir (Əlavə A). Məhsula zəmanətlər, işçi mükafatları planları və bəzi digər müqavilələr standartın əhatəsinə daxil deyil (m. 7).',
        'Azərbaycanda sığortaçılar və təkrarsığortaçılar ictimai əhəmiyyətli qurumlardır (Qanun, m. 2.1.9); onlar üçün Maliyyə Nazirliyi MHBS-ə əsasən mühasibat uçotunun aparılmasının ayrıca Qaydalarını təsdiq etmişdir.'),
    ]);
})();
